CREATE TABLE IF NOT EXISTS workspaces (id VARCHAR(64) PRIMARY KEY, name VARCHAR(255) NOT NULL, mode VARCHAR(32) NOT NULL DEFAULT 'local', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS projects (id VARCHAR(64) PRIMARY KEY, workspace_id VARCHAR(64) NOT NULL, name VARCHAR(255) NOT NULL, repository VARCHAR(512), status VARCHAR(32) NOT NULL DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (workspace_id) REFERENCES workspaces(id));
CREATE TABLE IF NOT EXISTS workshops (id VARCHAR(64) PRIMARY KEY, project_id VARCHAR(64), name VARCHAR(255) NOT NULL, environment VARCHAR(64) NOT NULL, platform VARCHAR(64), model_id VARCHAR(128), voice_id VARCHAR(128), branch_name VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (project_id) REFERENCES projects(id));
CREATE TABLE IF NOT EXISTS agents (id VARCHAR(64) PRIMARY KEY, name VARCHAR(255) NOT NULL, role VARCHAR(128), model_id VARCHAR(128), system_prompt TEXT, temperature DECIMAL(4,3) DEFAULT 0.2, memory_scope VARCHAR(32) DEFAULT 'project', enabled BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS clusters (id VARCHAR(64) PRIMARY KEY, project_id VARCHAR(64), name VARCHAR(255) NOT NULL, status VARCHAR(32) DEFAULT 'idle', max_parallel_agents INT DEFAULT 12, FOREIGN KEY (project_id) REFERENCES projects(id));
CREATE TABLE IF NOT EXISTS cluster_agents (cluster_id VARCHAR(64) NOT NULL, agent_id VARCHAR(64) NOT NULL, PRIMARY KEY (cluster_id, agent_id), FOREIGN KEY (cluster_id) REFERENCES clusters(id), FOREIGN KEY (agent_id) REFERENCES agents(id));
CREATE TABLE IF NOT EXISTS tasks (id VARCHAR(64) PRIMARY KEY, project_id VARCHAR(64), cluster_id VARCHAR(64), title VARCHAR(500) NOT NULL, status VARCHAR(32) DEFAULT 'queued', priority VARCHAR(16) DEFAULT 'medium', assigned_agent_id VARCHAR(64), environment_id VARCHAR(64), depends_on VARCHAR(64), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (project_id) REFERENCES projects(id), FOREIGN KEY (cluster_id) REFERENCES clusters(id), FOREIGN KEY (assigned_agent_id) REFERENCES agents(id));
CREATE TABLE IF NOT EXISTS memories (id VARCHAR(64) PRIMARY KEY, project_id VARCHAR(64), scope VARCHAR(32) NOT NULL, content LONGTEXT NOT NULL, source VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (project_id) REFERENCES projects(id));
CREATE TABLE IF NOT EXISTS artifacts (id VARCHAR(64) PRIMARY KEY, project_id VARCHAR(64), workshop_id VARCHAR(64), kind VARCHAR(64) NOT NULL, path VARCHAR(1024), content LONGTEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (project_id) REFERENCES projects(id), FOREIGN KEY (workshop_id) REFERENCES workshops(id));
CREATE TABLE IF NOT EXISTS blueprints (id VARCHAR(64) PRIMARY KEY, project_id VARCHAR(64), name VARCHAR(255) NOT NULL, target_language VARCHAR(64) NOT NULL, graph_json JSON NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (project_id) REFERENCES projects(id));
CREATE TABLE IF NOT EXISTS settings (setting_key VARCHAR(255) PRIMARY KEY, setting_value JSON NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_log (id BIGINT AUTO_INCREMENT PRIMARY KEY, action_name VARCHAR(255) NOT NULL, actor VARCHAR(255), resource_id VARCHAR(255), details JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
